const fs=require('fs'),path=require('path'),{execSync}=require('child_process');
const files={"frontend/src/app/(marketing)/layout.tsx":"\"use client\";\nimport Link from \"next/link\";\nimport { usePathname } from \"next/navigation\";\nimport { useState, useEffect } from \"react\";\nimport { motion, AnimatePresence } from \"framer-motion\";\nimport { Menu, X, ArrowRight } from \"lucide-react\";\n\n// Unified color system matching auth + dashboard + landing page\nconst C = {\n  bg:     \"#F4F2FB\",\n  navy:   \"#130D2E\",\n  purple: \"#6B35E8\",\n  muted:  \"rgba(19,13,46,0.5)\",\n  border: \"rgba(107,53,232,0.1)\",\n};\n\nconst NAV_LINKS = [\n  { href: \"/features\",     label: \"Features\"     },\n  { href: \"/pricing\",      label: \"Pricing\"      },\n  { href: \"/how-it-works\", label: \"How it works\" },\n  { href: \"/about\",        label: \"About\"        },\n];\n\nconst FOOTER = [\n  {\n    title: \"Product\",\n    links: [\n      [\"Features\",     \"/features\"     ],\n      [\"How it Works\", \"/how-it-works\" ],\n      [\"Pricing\",      \"/pricing\"      ],\n      [\"Security\",     \"/security\"     ],\n    ],\n  },\n  {\n    title: \"Company\",\n    links: [\n      [\"About\",   \"/about\"   ],\n      [\"Contact\", \"/contact\" ],\n    ],\n  },\n  {\n    title: \"Legal\",\n    links: [\n      [\"Privacy Policy\", \"/privacy\" ],\n      [\"Terms of Use\",   \"/terms\"   ],\n      [\"Cookie Policy\",  \"/cookies\" ],\n    ],\n  },\n];\n\nfunction Logo() {\n  return (\n    <Link href=\"/\" style={{ display:\"flex\", alignItems:\"center\", gap:10, textDecoration:\"none\" }}>\n      <div style={{\n        width:32, height:32, borderRadius:9,\n        background:\"linear-gradient(145deg,#2D1B69,#0D0625)\",\n        display:\"flex\", alignItems:\"center\", justifyContent:\"center\",\n        boxShadow:\"0 4px 12px rgba(45,27,105,0.3)\",\n      }}>\n        <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\">\n          <path d=\"M13 2L3 14h9l-1 8 10-12h-9z\" fill=\"white\"/>\n        </svg>\n      </div>\n      <span style={{ fontSize:16, fontWeight:800, color:C.navy, letterSpacing:\"-0.02em\" }}>\n        Drop<span style={{ color:C.purple }}>OS</span>\n      </span>\n    </Link>\n  );\n}\n\nfunction Nav() {\n  const pathname = usePathname();\n  const [scrolled, setScrolled] = useState(false);\n  const [open, setOpen] = useState(false);\n\n  useEffect(() => {\n    const fn = () => setScrolled(window.scrollY > 20);\n    window.addEventListener(\"scroll\", fn, { passive:true });\n    return () => window.removeEventListener(\"scroll\", fn);\n  }, []);\n  useEffect(() => { setOpen(false); }, [pathname]);\n\n  return (\n    <>\n      <header style={{\n        position:\"fixed\", top:0, left:0, right:0, zIndex:100,\n        height:64, display:\"flex\", alignItems:\"center\",\n        padding:\"0 24px\",\n        background: scrolled ? \"rgba(244,242,251,0.95)\" : \"transparent\",\n        backdropFilter: scrolled ? \"blur(20px)\" : \"none\",\n        borderBottom: scrolled ? `1px solid ${C.border}` : \"1px solid transparent\",\n        transition:\"all 0.25s ease\",\n      }}>\n        <Logo />\n\n        {/* Desktop links */}\n        <nav style={{ flex:1, display:\"flex\", alignItems:\"center\", justifyContent:\"center\", gap:4 }} className=\"mkt-nav\">\n          {NAV_LINKS.map(l => (\n            <Link key={l.href} href={l.href}\n              style={{\n                fontSize:13, fontWeight:500, textDecoration:\"none\", padding:\"7px 14px\", borderRadius:9,\n                color: pathname === l.href ? C.navy : C.muted,\n                background: pathname === l.href ? \"rgba(107,53,232,0.06)\" : \"transparent\",\n                transition:\"all 0.15s\",\n              }}\n              onMouseEnter={e => { e.currentTarget.style.color=C.navy; e.currentTarget.style.background=\"rgba(107,53,232,0.06)\"; }}\n              onMouseLeave={e => {\n                e.currentTarget.style.color = pathname===l.href ? C.navy : C.muted;\n                e.currentTarget.style.background = pathname===l.href ? \"rgba(107,53,232,0.06)\" : \"transparent\";\n              }}>\n              {l.label}\n            </Link>\n          ))}\n        </nav>\n\n        {/* CTA */}\n        <div style={{ display:\"flex\", alignItems:\"center\", gap:10 }} className=\"mkt-cta\">\n          <Link href=\"/auth/login\" style={{ fontSize:13, fontWeight:600, color:C.muted, textDecoration:\"none\", padding:\"8px 14px\", borderRadius:8, transition:\"color 0.15s\" }}>\n            Sign in\n          </Link>\n          <Link href=\"/auth/register\" style={{\n            display:\"flex\", alignItems:\"center\", gap:6,\n            fontSize:13, fontWeight:700, color:\"#fff\", textDecoration:\"none\",\n            padding:\"9px 18px\", borderRadius:10,\n            background:C.navy,\n            boxShadow:\"0 4px 14px rgba(19,13,46,0.18)\",\n          }}>\n            Start free <ArrowRight size={13}/>\n          </Link>\n        </div>\n\n        {/* Mobile hamburger */}\n        <button onClick={() => setOpen(!open)} className=\"mkt-burger\"\n          style={{ display:\"none\", background:\"none\", border:\"none\", cursor:\"pointer\", color:C.navy, padding:4, marginLeft:\"auto\" }}>\n          {open ? <X size={22}/> : <Menu size={22}/>}\n        </button>\n      </header>\n\n      {/* Mobile menu */}\n      <AnimatePresence>\n        {open && (\n          <motion.div initial={{ opacity:0, y:-8 }} animate={{ opacity:1, y:0 }} exit={{ opacity:0, y:-8 }}\n            style={{\n              position:\"fixed\", top:64, left:0, right:0, zIndex:99,\n              background:\"rgba(244,242,251,0.98)\", backdropFilter:\"blur(20px)\",\n              borderBottom:`1px solid ${C.border}`, padding:\"16px 24px 24px\",\n              display:\"flex\", flexDirection:\"column\", gap:4,\n            }}>\n            {NAV_LINKS.map(l => (\n              <Link key={l.href} href={l.href} onClick={() => setOpen(false)}\n                style={{ fontSize:15, fontWeight:600, color:C.navy, textDecoration:\"none\", padding:\"12px 0\", borderBottom:`1px solid ${C.border}` }}>\n                {l.label}\n              </Link>\n            ))}\n            <Link href=\"/auth/register\" onClick={() => setOpen(false)}\n              style={{ marginTop:12, display:\"flex\", alignItems:\"center\", justifyContent:\"center\", gap:6, padding:\"14px 0\", borderRadius:12, background:C.navy, color:\"#fff\", textDecoration:\"none\", fontSize:15, fontWeight:700 }}>\n              Start free <ArrowRight size={14}/>\n            </Link>\n          </motion.div>\n        )}\n      </AnimatePresence>\n\n      <style>{`\n        @media(max-width:768px){ .mkt-nav,.mkt-cta{display:none!important;} .mkt-burger{display:flex!important;} }\n      `}</style>\n    </>\n  );\n}\n\nfunction Footer() {\n  return (\n    <footer style={{ background:\"#fff\", borderTop:`1px solid ${C.border}`, paddingTop:56, paddingBottom:32, fontFamily:\"'Plus Jakarta Sans',system-ui,sans-serif\" }}>\n      <div style={{ maxWidth:1080, margin:\"0 auto\", padding:\"0 24px\" }}>\n        <div style={{ display:\"grid\", gridTemplateColumns:\"2fr 1fr 1fr 1fr\", gap:40, marginBottom:48 }} className=\"footer-grid\">\n          {/* Brand */}\n          <div>\n            <Logo />\n            <p style={{ fontSize:13, color:C.muted, marginTop:14, lineHeight:1.65, maxWidth:240 }}>\n              The AI-powered commerce platform. Launch your store in 60 seconds.\n            </p>\n            <div style={{ display:\"flex\", alignItems:\"center\", gap:6, marginTop:16 }}>\n              <div style={{ width:7, height:7, borderRadius:\"50%\", background:\"#10B981\" }}/>\n              <span style={{ fontSize:11, color:\"rgba(19,13,46,0.4)\", fontWeight:500 }}>All systems operational</span>\n            </div>\n          </div>\n\n          {/* Link columns */}\n          {FOOTER.map(col => (\n            <div key={col.title}>\n              <p style={{ fontSize:11, fontWeight:700, letterSpacing:\"0.1em\", color:C.muted, textTransform:\"uppercase\", marginBottom:16 }}>\n                {col.title}\n              </p>\n              <div style={{ display:\"flex\", flexDirection:\"column\", gap:10 }}>\n                {col.links.map(([label, href]) => (\n                  <Link key={label} href={href}\n                    style={{ fontSize:13, color:C.muted, textDecoration:\"none\", fontWeight:500, transition:\"color 0.15s\" }}\n                    onMouseEnter={e => e.currentTarget.style.color=C.navy}\n                    onMouseLeave={e => e.currentTarget.style.color=C.muted}>\n                    {label}\n                  </Link>\n                ))}\n              </div>\n            </div>\n          ))}\n        </div>\n\n        <div style={{ borderTop:`1px solid ${C.border}`, paddingTop:24, display:\"flex\", alignItems:\"center\", justifyContent:\"space-between\", flexWrap:\"wrap\", gap:12 }}>\n          <p style={{ fontSize:12, color:C.muted }}>© 2026 DropOS. All rights reserved.</p>\n          <p style={{ fontSize:12, color:C.muted }}>Built for merchants who move fast 🚀</p>\n        </div>\n      </div>\n\n      <style>{`@media(max-width:768px){ .footer-grid{grid-template-columns:1fr 1fr!important; gap:32px!important;} }`}</style>\n    </footer>\n  );\n}\n\nexport default function MarketingLayout({ children }: { children: React.ReactNode }) {\n  return (\n    <div style={{ background:C.bg, minHeight:\"100vh\", fontFamily:\"'Plus Jakarta Sans',system-ui,sans-serif\" }}>\n      <style>{`\n        @import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800;900&family=Fraunces:ital,wght@0,400;0,500;0,600;0,700;1,400;1,500;1,600;1,700&display=swap');\n        *{box-sizing:border-box;}\n      `}</style>\n      <Nav />\n      <main style={{ paddingTop:64 }}>\n        {children}\n      </main>\n      <Footer />\n    </div>\n  );\n}\n","frontend/src/components/HomePage.tsx":"\"use client\";\nimport { useState, useEffect, useRef } from \"react\";\nimport { motion, useScroll, useTransform, AnimatePresence } from \"framer-motion\";\nimport Link from \"next/link\";\nimport {\n  Zap, ArrowRight, Check, Store, Package, BarChart3,\n  ShoppingCart, Globe, Shield, TrendingUp, Sparkles,\n  ChevronRight, Star, Play, Menu, X, MessageSquare,\n} from \"lucide-react\";\n\n// ─── Brand colors (matches dashboard + auth) ─────────────────────────────────\nconst C = {\n  bg:      \"#F4F2FB\",\n  navy:    \"#130D2E\",\n  purple:  \"#6B35E8\",\n  violet:  \"#2D1B69\",\n  muted:   \"rgba(19,13,46,0.5)\",\n  faint:   \"rgba(107,53,232,0.06)\",\n  border:  \"rgba(107,53,232,0.1)\",\n};\n\nconst API = process.env.NEXT_PUBLIC_API_URL || \"https://dropos-v2.onrender.com/api\";\n\n// ─── Nav ──────────────────────────────────────────────────────────────────────\nfunction Nav() {\n  const [scrolled, setScrolled] = useState(false);\n  const [mobileOpen, setMobileOpen] = useState(false);\n\n  useEffect(() => {\n    const fn = () => setScrolled(window.scrollY > 20);\n    window.addEventListener(\"scroll\", fn);\n    return () => window.removeEventListener(\"scroll\", fn);\n  }, []);\n\n  return (\n    <>\n      <nav style={{\n        position: \"fixed\", top: 0, left: 0, right: 0, zIndex: 100,\n        padding: \"0 24px\",\n        height: 64,\n        display: \"flex\", alignItems: \"center\", justifyContent: \"space-between\",\n        background: scrolled ? \"rgba(244,242,251,0.92)\" : \"transparent\",\n        backdropFilter: scrolled ? \"blur(20px)\" : \"none\",\n        borderBottom: scrolled ? `1px solid ${C.border}` : \"1px solid transparent\",\n        transition: \"all 0.3s ease\",\n      }}>\n        {/* Logo */}\n        <Link href=\"/\" style={{ display: \"flex\", alignItems: \"center\", gap: 10, textDecoration: \"none\" }}>\n          <div style={{\n            width: 32, height: 32, borderRadius: 9,\n            background: \"linear-gradient(145deg,#2D1B69,#0D0625)\",\n            display: \"flex\", alignItems: \"center\", justifyContent: \"center\",\n            boxShadow: \"0 4px 12px rgba(45,27,105,0.3)\",\n          }}>\n            <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\">\n              <path d=\"M13 2L3 14h9l-1 8 10-12h-9z\" fill=\"white\"/>\n            </svg>\n          </div>\n          <span style={{ fontSize: 16, fontWeight: 800, color: C.navy, letterSpacing: \"-0.02em\" }}>DropOS</span>\n        </Link>\n\n        {/* Desktop nav */}\n        <div className=\"nav-links\" style={{ display: \"flex\", alignItems: \"center\", gap: 6 }}>\n          {[\n            { label: \"Features\",   href: \"/#features\"  },\n            { label: \"Pricing\",    href: \"/pricing\"    },\n            { label: \"How it works\", href: \"/how-it-works\" },\n          ].map(l => (\n            <Link key={l.label} href={l.href}\n              style={{ fontSize: 13, fontWeight: 500, color: C.muted, textDecoration: \"none\", padding: \"6px 12px\", borderRadius: 8, transition: \"all 0.15s\" }}\n              onMouseEnter={e => { e.currentTarget.style.color = C.navy; e.currentTarget.style.background = C.faint; }}\n              onMouseLeave={e => { e.currentTarget.style.color = C.muted; e.currentTarget.style.background = \"transparent\"; }}>\n              {l.label}\n            </Link>\n          ))}\n        </div>\n\n        {/* CTA */}\n        <div className=\"nav-cta\" style={{ display: \"flex\", alignItems: \"center\", gap: 10 }}>\n          <Link href=\"/auth/login\" style={{ fontSize: 13, fontWeight: 600, color: C.muted, textDecoration: \"none\", padding: \"8px 14px\", borderRadius: 8 }}>\n            Sign in\n          </Link>\n          <Link href=\"/auth/register\" style={{\n            fontSize: 13, fontWeight: 700, color: \"#fff\", textDecoration: \"none\",\n            padding: \"9px 18px\", borderRadius: 10,\n            background: C.navy,\n            boxShadow: \"0 4px 14px rgba(19,13,46,0.2)\",\n            display: \"flex\", alignItems: \"center\", gap: 6,\n          }}>\n            Start free <ArrowRight size={13}/>\n          </Link>\n        </div>\n\n        {/* Mobile hamburger */}\n        <button className=\"nav-mobile-btn\" onClick={() => setMobileOpen(!mobileOpen)}\n          style={{ display: \"none\", background: \"none\", border: \"none\", cursor: \"pointer\", color: C.navy, padding: 4 }}>\n          {mobileOpen ? <X size={22}/> : <Menu size={22}/>}\n        </button>\n      </nav>\n\n      {/* Mobile menu */}\n      <AnimatePresence>\n        {mobileOpen && (\n          <motion.div initial={{ opacity: 0, y: -10 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -10 }}\n            style={{\n              position: \"fixed\", top: 64, left: 0, right: 0, zIndex: 99,\n              background: \"rgba(244,242,251,0.98)\", backdropFilter: \"blur(20px)\",\n              borderBottom: `1px solid ${C.border}`, padding: \"16px 24px 24px\",\n              display: \"flex\", flexDirection: \"column\", gap: 4,\n            }}>\n            {[\"Features\", \"Pricing\", \"How it works\"].map(l => (\n              <Link key={l} href={`/${l.toLowerCase().replace(/ /g, \"-\")}`}\n                onClick={() => setMobileOpen(false)}\n                style={{ fontSize: 15, fontWeight: 600, color: C.navy, textDecoration: \"none\", padding: \"12px 0\", borderBottom: `1px solid ${C.border}` }}>\n                {l}\n              </Link>\n            ))}\n            <Link href=\"/auth/register\" onClick={() => setMobileOpen(false)}\n              style={{ marginTop: 12, display: \"flex\", alignItems: \"center\", justifyContent: \"center\", gap: 6, padding: \"14px 0\", borderRadius: 12, background: C.navy, color: \"#fff\", textDecoration: \"none\", fontSize: 15, fontWeight: 700 }}>\n              Start free <ArrowRight size={14}/>\n            </Link>\n          </motion.div>\n        )}\n      </AnimatePresence>\n\n      <style>{`\n        @media(max-width:768px){ .nav-links,.nav-cta{display:none!important;} .nav-mobile-btn{display:flex!important;} }\n      `}</style>\n    </>\n  );\n}\n\n// ─── Hero ─────────────────────────────────────────────────────────────────────\nfunction Hero() {\n  const [email, setEmail] = useState(\"\");\n  const [submitted, setSubmitted] = useState(false);\n  const [loading, setLoading] = useState(false);\n\n  const join = async () => {\n    if (!email || loading) return;\n    setLoading(true);\n    try {\n      await fetch(`${API}/waitlist`, {\n        method: \"POST\", headers: { \"Content-Type\": \"application/json\" },\n        body: JSON.stringify({ email, source: \"homepage\" }),\n      });\n    } catch {}\n    setSubmitted(true);\n    setLoading(false);\n  };\n\n  return (\n    <section style={{\n      minHeight: \"100vh\",\n      display: \"flex\", flexDirection: \"column\", alignItems: \"center\", justifyContent: \"center\",\n      padding: \"120px 24px 80px\",\n      textAlign: \"center\",\n      position: \"relative\",\n      overflow: \"hidden\",\n    }}>\n      {/* Ambient background */}\n      <div style={{\n        position: \"absolute\", top: \"10%\", left: \"50%\", transform: \"translateX(-50%)\",\n        width: 700, height: 700, borderRadius: \"50%\",\n        background: \"radial-gradient(circle, rgba(107,53,232,0.08) 0%, transparent 65%)\",\n        filter: \"blur(60px)\", pointerEvents: \"none\",\n      }}/>\n\n      {/* Badge */}\n      <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.5 }}\n        style={{\n          display: \"inline-flex\", alignItems: \"center\", gap: 8,\n          padding: \"6px 14px 6px 6px\", borderRadius: 99,\n          background: \"#fff\", border: `1px solid ${C.border}`,\n          marginBottom: 28, boxShadow: \"0 2px 12px rgba(107,53,232,0.08)\",\n        }}>\n        <span style={{\n          fontSize: 10, fontWeight: 800, letterSpacing: \"0.08em\",\n          background: C.navy, color: \"#fff\",\n          padding: \"3px 8px\", borderRadius: 99,\n        }}>NEW</span>\n        <span style={{ fontSize: 12, color: C.muted, fontWeight: 500 }}>\n          KIRO AI now has 22 smart commands\n        </span>\n        <ChevronRight size={12} style={{ color: C.muted }}/>\n      </motion.div>\n\n      {/* Headline */}\n      <motion.h1 initial={{ opacity: 0, y: 16 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.6, delay: 0.1 }}\n        style={{\n          fontFamily: \"'Fraunces', Georgia, serif\",\n          fontSize: \"clamp(40px, 7vw, 76px)\",\n          fontWeight: 500, letterSpacing: \"-0.04em\",\n          color: C.navy, lineHeight: 1.04,\n          maxWidth: 800, margin: \"0 0 20px\",\n        }}>\n        The smarter way<br/>\n        <em style={{ fontStyle: \"italic\", color: C.purple }}>to dropship.</em>\n      </motion.h1>\n\n      {/* Subheading */}\n      <motion.p initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.6, delay: 0.2 }}\n        style={{ fontSize: \"clamp(15px, 2.5vw, 18px)\", color: C.muted, maxWidth: 520, lineHeight: 1.6, marginBottom: 40 }}>\n        Launch your store in 60 seconds. Import from any supplier worldwide.\n        Let KIRO handle the copy, pricing, and sales — so you focus on growing.\n      </motion.p>\n\n      {/* CTA */}\n      <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.5, delay: 0.3 }}\n        style={{ display: \"flex\", gap: 10, flexWrap: \"wrap\", justifyContent: \"center\" }}>\n        <Link href=\"/auth/register\" style={{\n          display: \"flex\", alignItems: \"center\", gap: 8,\n          padding: \"15px 28px\", borderRadius: 14,\n          background: C.navy, color: \"#fff\",\n          textDecoration: \"none\", fontSize: 15, fontWeight: 700,\n          boxShadow: \"0 8px 28px rgba(19,13,46,0.22)\",\n          letterSpacing: \"-0.01em\",\n          transition: \"all 0.15s\",\n        }}\n        onMouseEnter={e => { e.currentTarget.style.transform = \"translateY(-2px)\"; e.currentTarget.style.boxShadow = \"0 12px 36px rgba(19,13,46,0.3)\"; }}\n        onMouseLeave={e => { e.currentTarget.style.transform = \"translateY(0)\"; e.currentTarget.style.boxShadow = \"0 8px 28px rgba(19,13,46,0.22)\"; }}>\n          Start for free <ArrowRight size={15}/>\n        </Link>\n        <Link href=\"/auth/login\" style={{\n          display: \"flex\", alignItems: \"center\", gap: 8,\n          padding: \"15px 28px\", borderRadius: 14,\n          background: \"#fff\", color: C.navy,\n          textDecoration: \"none\", fontSize: 15, fontWeight: 600,\n          border: `1px solid ${C.border}`,\n          boxShadow: \"0 2px 12px rgba(107,53,232,0.06)\",\n          transition: \"all 0.15s\",\n        }}>\n          Sign in\n        </Link>\n      </motion.div>\n\n      {/* Trust signals */}\n      <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 0.5 }}\n        style={{ display: \"flex\", flexWrap: \"wrap\", alignItems: \"center\", justifyContent: \"center\", gap: \"8px 24px\", marginTop: 36 }}>\n        {[\n          \"No credit card required\",\n          \"Free plan available\",\n          \"Paystack + Stripe payments\",\n          \"29 store templates\",\n        ].map(f => (\n          <span key={f} style={{ display: \"flex\", alignItems: \"center\", gap: 6, fontSize: 12, color: C.muted }}>\n            <Check size={11} color={C.purple} strokeWidth={2.5}/>\n            {f}\n          </span>\n        ))}\n      </motion.div>\n\n      {/* Dashboard preview */}\n      <motion.div initial={{ opacity: 0, y: 40 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.8, delay: 0.4 }}\n        style={{ width: \"100%\", maxWidth: 960, marginTop: 72, position: \"relative\" }}>\n        {/* Glow under the preview */}\n        <div style={{\n          position: \"absolute\", bottom: -40, left: \"10%\", right: \"10%\",\n          height: 80, borderRadius: \"50%\",\n          background: \"radial-gradient(ellipse, rgba(107,53,232,0.15), transparent)\",\n          filter: \"blur(20px)\",\n        }}/>\n        <div style={{\n          borderRadius: 20, overflow: \"hidden\",\n          border: `1px solid ${C.border}`,\n          boxShadow: \"0 32px 80px rgba(19,13,46,0.12), 0 2px 4px rgba(19,13,46,0.04)\",\n          background: \"#fff\",\n          position: \"relative\",\n        }}>\n          {/* Browser chrome */}\n          <div style={{\n            background: \"#F4F2FB\", padding: \"12px 16px\",\n            borderBottom: `1px solid ${C.border}`,\n            display: \"flex\", alignItems: \"center\", gap: 8,\n          }}>\n            <div style={{ display: \"flex\", gap: 5 }}>\n              {[\"#EF4444\",\"#F59E0B\",\"#10B981\"].map(c => (\n                <div key={c} style={{ width: 10, height: 10, borderRadius: \"50%\", background: c }}/>\n              ))}\n            </div>\n            <div style={{\n              flex: 1, maxWidth: 240, margin: \"0 auto\",\n              background: \"#fff\", borderRadius: 6, padding: \"4px 12px\",\n              fontSize: 11, color: C.muted, textAlign: \"center\", border: `1px solid ${C.border}`,\n            }}>\n              droposhq.com/dashboard\n            </div>\n          </div>\n          {/* Dashboard mock */}\n          <div style={{ background: \"#F4F2FB\", padding: 20, display: \"flex\", gap: 14, minHeight: 320 }}>\n            {/* Sidebar */}\n            <div style={{ width: 48, background: \"#fff\", borderRadius: 12, padding: \"16px 0\", display: \"flex\", flexDirection: \"column\", alignItems: \"center\", gap: 16, border: `1px solid ${C.border}` }}>\n              <div style={{ width: 28, height: 28, borderRadius: 8, background: \"linear-gradient(145deg,#2D1B69,#0D0625)\", display: \"flex\", alignItems: \"center\", justifyContent: \"center\" }}>\n                <svg width=\"11\" height=\"11\" viewBox=\"0 0 24 24\" fill=\"none\"><path d=\"M13 2L3 14h9l-1 8 10-12h-9z\" fill=\"white\"/></svg>\n              </div>\n              {[Zap, Package, ShoppingCart, BarChart3, Store].map((Icon, i) => (\n                <div key={i} style={{ width: 32, height: 32, borderRadius: 8, display: \"flex\", alignItems: \"center\", justifyContent: \"center\", background: i === 0 ? \"rgba(107,53,232,0.1)\" : \"transparent\" }}>\n                  <Icon size={14} color={i === 0 ? C.purple : \"rgba(19,13,46,0.3)\"}/>\n                </div>\n              ))}\n            </div>\n            {/* Content */}\n            <div style={{ flex: 1, display: \"flex\", flexDirection: \"column\", gap: 12 }}>\n              {/* Stats row */}\n              <div style={{ display: \"grid\", gridTemplateColumns: \"repeat(4,1fr)\", gap: 10 }}>\n                {[\n                  { label: \"Revenue\", value: \"₦284,000\", up: true },\n                  { label: \"Orders\",  value: \"42\",        up: true },\n                  { label: \"Products\",value: \"186\",       up: false },\n                  { label: \"Visitors\",value: \"1,240\",     up: true },\n                ].map(s => (\n                  <div key={s.label} style={{ background: \"#fff\", borderRadius: 12, padding: \"14px 12px\", border: `1px solid ${C.border}` }}>\n                    <p style={{ fontSize: 9, color: C.muted, margin: \"0 0 4px\", textTransform: \"uppercase\", letterSpacing: \"0.05em\" }}>{s.label}</p>\n                    <p style={{ fontSize: 17, fontWeight: 800, color: C.navy, margin: 0 }}>{s.value}</p>\n                    <p style={{ fontSize: 9, color: s.up ? \"#10B981\" : \"#EF4444\", margin: \"2px 0 0\" }}>{s.up ? \"↑\" : \"↓\"} this month</p>\n                  </div>\n                ))}\n              </div>\n              {/* KIRO chat */}\n              <div style={{ background: \"#fff\", borderRadius: 12, padding: 16, border: `1px solid ${C.border}`, flex: 1 }}>\n                <div style={{ display: \"flex\", alignItems: \"center\", gap: 8, marginBottom: 12 }}>\n                  <div style={{ width: 24, height: 24, borderRadius: 6, background: \"linear-gradient(145deg,#7c3aed,#4c1d95)\", display: \"flex\", alignItems: \"center\", justifyContent: \"center\" }}>\n                    <Zap size={11} color=\"#fff\"/>\n                  </div>\n                  <span style={{ fontSize: 11, fontWeight: 700, color: C.navy }}>KIRO</span>\n                  <span style={{ fontSize: 9, color: \"#10B981\", background: \"rgba(16,185,129,0.1)\", padding: \"2px 6px\", borderRadius: 99 }}>● Ready</span>\n                </div>\n                <div style={{ background: \"#F4F2FB\", borderRadius: 10, padding: \"10px 14px\", marginBottom: 8 }}>\n                  <p style={{ fontSize: 11, color: C.navy, margin: 0 }}>Your store made ₦47,000 this week. Want me to run a flash sale to hit ₦100k by Sunday?</p>\n                </div>\n                <div style={{ display: \"flex\", gap: 6 }}>\n                  {[\"Yes, let's go\", \"Show me the plan\", \"Not now\"].map(a => (\n                    <button key={a} style={{ fontSize: 9, padding: \"5px 10px\", borderRadius: 6, border: `1px solid ${C.border}`, background: \"#fff\", color: C.muted, cursor: \"pointer\", fontFamily: \"inherit\" }}>{a}</button>\n                  ))}\n                </div>\n              </div>\n            </div>\n          </div>\n        </div>\n      </motion.div>\n    </section>\n  );\n}\n\n// ─── Features ─────────────────────────────────────────────────────────────────\nconst FEATURES = [\n  {\n    icon: Sparkles,\n    color: \"#7C3AED\",\n    title: \"KIRO AI — your commerce brain\",\n    desc: \"Import products, write descriptions, run flash sales, recover abandoned carts, and get daily insights — all from a single chat.\",\n    tags: [\"22 slash commands\", \"Proactive alerts\", \"Daily brief\"],\n  },\n  {\n    icon: Store,\n    color: \"#0EA5E9\",\n    title: \"29 store templates\",\n    desc: \"From fashion to food to electronics — pick a template that matches your brand. Customize colors, fonts, and layout in seconds.\",\n    tags: [\"Fashion\", \"Beauty\", \"Electronics\", \"+26 more\"],\n  },\n  {\n    icon: Package,\n    color: \"#10B981\",\n    title: \"One-click supplier import\",\n    desc: \"Paste any AliExpress, Temu, or Amazon link. KIRO scrapes it, scores it A–F, and sets a margin price that actually makes you money.\",\n    tags: [\"AliExpress\", \"Temu\", \"Amazon\", \"CJDropshipping\"],\n  },\n  {\n    icon: TrendingUp,\n    color: \"#F59E0B\",\n    title: \"Paystack + Stripe payments\",\n    desc: \"Accept Naira payments via Paystack. Accept global card payments via Stripe. Both wired in — no code needed.\",\n    tags: [\"Card\", \"Bank transfer\", \"USSD\", \"International\"],\n  },\n  {\n    icon: BarChart3,\n    color: \"#EF4444\",\n    title: \"Smart analytics\",\n    desc: \"Revenue, orders, conversion rate, top products. KIRO reads your numbers and tells you what to do about them.\",\n    tags: [\"Revenue\", \"Conversion\", \"Products\", \"Customers\"],\n  },\n  {\n    icon: MessageSquare,\n    color: \"#8B5CF6\",\n    title: \"Opportunity engine\",\n    desc: \"KIRO scans your store every 6 hours for price wins, bundle opportunities, abandoned cart value, and seasonal moments.\",\n    tags: [\"Pricing AI\", \"Bundle detection\", \"Win-back\", \"Seasonal\"],\n  },\n];\n\nfunction Features() {\n  return (\n    <section id=\"features\" style={{ padding: \"100px 24px\", maxWidth: 1080, margin: \"0 auto\" }}>\n      <div style={{ textAlign: \"center\", marginBottom: 64 }}>\n        <p style={{ fontSize: 12, fontWeight: 700, letterSpacing: \"0.12em\", color: C.purple, marginBottom: 12, textTransform: \"uppercase\" }}>\n          EVERYTHING YOU NEED\n        </p>\n        <h2 style={{\n          fontFamily: \"'Fraunces', Georgia, serif\",\n          fontSize: \"clamp(32px, 5vw, 52px)\", fontWeight: 500, letterSpacing: \"-0.035em\",\n          color: C.navy, margin: \"0 0 16px\", lineHeight: 1.1,\n        }}>\n          Everything you need,<br/>\n          <em style={{ fontStyle: \"italic\", color: C.purple }}>nothing you don't.</em>\n        </h2>\n        <p style={{ fontSize: 16, color: C.muted, maxWidth: 480, margin: \"0 auto\", lineHeight: 1.6 }}>\n          Every feature is designed to help you sell more, work less, and grow faster.\n        </p>\n      </div>\n\n      <div style={{ display: \"grid\", gridTemplateColumns: \"repeat(3,1fr)\", gap: 16 }} className=\"feat-grid\">\n        {FEATURES.map((f, i) => {\n          const Icon = f.icon;\n          return (\n            <motion.div key={f.title}\n              initial={{ opacity: 0, y: 16 }} whileInView={{ opacity: 1, y: 0 }}\n              transition={{ delay: i * 0.08 }} viewport={{ once: true }}\n              style={{\n                background: \"#fff\", borderRadius: 20, padding: 24,\n                border: `1px solid ${C.border}`,\n                boxShadow: \"0 2px 12px rgba(107,53,232,0.05)\",\n                transition: \"all 0.2s\",\n              }}\n              whileHover={{ y: -4, boxShadow: \"0 8px 32px rgba(107,53,232,0.1)\" }}>\n              <div style={{\n                width: 44, height: 44, borderRadius: 12, marginBottom: 16,\n                background: `${f.color}12`,\n                display: \"flex\", alignItems: \"center\", justifyContent: \"center\",\n              }}>\n                <Icon size={20} color={f.color}/>\n              </div>\n              <h3 style={{ fontSize: 15, fontWeight: 700, color: C.navy, margin: \"0 0 8px\", letterSpacing: \"-0.02em\" }}>{f.title}</h3>\n              <p style={{ fontSize: 13, color: C.muted, lineHeight: 1.6, margin: \"0 0 16px\" }}>{f.desc}</p>\n              <div style={{ display: \"flex\", flexWrap: \"wrap\", gap: 6 }}>\n                {f.tags.map(t => (\n                  <span key={t} style={{ fontSize: 10, fontWeight: 600, padding: \"3px 9px\", borderRadius: 99, background: C.faint, color: C.purple, border: `1px solid ${C.border}` }}>\n                    {t}\n                  </span>\n                ))}\n              </div>\n            </motion.div>\n          );\n        })}\n      </div>\n\n      <style>{`@media(max-width:768px){ .feat-grid{grid-template-columns:1fr!important;} }`}</style>\n    </section>\n  );\n}\n\n// ─── Location-aware Pricing Preview ──────────────────────────────────────────\nconst PRICING_BY_REGION: Record<string, {\n  symbol: string; free: string; growth: string; pro: string;\n  period: string; tagline: string; badge?: string;\n}> = {\n  NG: { symbol:\"₦\", free:\"₦0\",     growth:\"₦9,500\",  pro:\"₦25,000\", period:\"/mo\", tagline:\"Pay in Naira. No forex stress.\", badge:\"🇳🇬 Nigerian prices\" },\n  GH: { symbol:\"₵\", free:\"₵0\",     growth:\"₵89\",     pro:\"₵240\",    period:\"/mo\", tagline:\"Priced for Ghana. Accept GHS payments.\", badge:\"🇬🇭 Ghana prices\" },\n  KE: { symbol:\"KSh\",free:\"KSh 0\", growth:\"KSh 1,300\",pro:\"KSh 3,500\",period:\"/mo\", tagline:\"Priced for Kenya. M-Pesa friendly.\", badge:\"🇰🇪 Kenya prices\" },\n  ZA: { symbol:\"R\",  free:\"R 0\",   growth:\"R 180\",   pro:\"R 470\",   period:\"/mo\", tagline:\"Priced for South Africa.\", badge:\"🇿🇦 South Africa prices\" },\n  GB: { symbol:\"£\",  free:\"£0\",    growth:\"£5\",      pro:\"£14\",     period:\"/mo\", tagline:\"Priced for the UK. Accept GBP.\", badge:\"🇬🇧 UK prices\" },\n  US: { symbol:\"$\",  free:\"$0\",    growth:\"$6\",      pro:\"$16\",     period:\"/mo\", tagline:\"Accept USD payments globally.\", badge:\"🇺🇸 US prices\" },\n  DEFAULT: { symbol:\"$\", free:\"$0\", growth:\"$6\",     pro:\"$16\",     period:\"/mo\", tagline:\"Accept payments in 50+ currencies.\", },\n};\n\nfunction detectRegion(): string {\n  if (typeof window === \"undefined\") return \"DEFAULT\";\n  try {\n    const tz = Intl.DateTimeFormat().resolvedOptions().timeZone;\n    if (tz.includes(\"Lagos\") || tz.includes(\"Abuja\")) return \"NG\";\n    if (tz.includes(\"Accra\")) return \"GH\";\n    if (tz.includes(\"Nairobi\")) return \"KE\";\n    if (tz.includes(\"Johannesburg\") || tz.includes(\"Cape_Town\")) return \"ZA\";\n    if (tz.includes(\"London\")) return \"GB\";\n    if (tz.includes(\"New_York\") || tz.includes(\"Los_Angeles\") || tz.includes(\"Chicago\")) return \"US\";\n    const lang = navigator.language || \"\";\n    if (lang.includes(\"en-NG\")) return \"NG\";\n    if (lang.includes(\"en-GH\")) return \"GH\";\n    if (lang.includes(\"en-KE\")) return \"KE\";\n    if (lang.includes(\"en-ZA\")) return \"ZA\";\n    if (lang.includes(\"en-GB\")) return \"GB\";\n    if (lang.includes(\"en-US\")) return \"US\";\n  } catch {}\n  return \"DEFAULT\";\n}\n\nfunction PricingPreview() {\n  const [region, setRegion] = useState(\"DEFAULT\");\n  useEffect(() => { setRegion(detectRegion()); }, []);\n  const p = PRICING_BY_REGION[region] || PRICING_BY_REGION.DEFAULT;\n\n  const plans = [\n    { name: \"Free\",   price: p.free,   features: [\"1 store\", \"20 products\", \"KIRO — 10 msg/day\", \"Basic analytics\"], highlight: false },\n    { name: \"Growth\", price: p.growth, features: [\"5 stores\", \"Unlimited products\", \"KIRO — unlimited\", \"Custom domain\", \"Priority support\"], highlight: true },\n    { name: \"Pro\",    price: p.pro,    features: [\"Unlimited stores\", \"Everything in Growth\", \"API access\", \"Dedicated support\"], highlight: false },\n  ];\n\n  return (\n    <section style={{ padding:\"80px 24px\", background:\"linear-gradient(160deg,#2D1B69 0%,#0D0625 100%)\" }}>\n      <div style={{ maxWidth:960, margin:\"0 auto\", textAlign:\"center\" }}>\n        <p style={{ fontSize:12, fontWeight:700, letterSpacing:\"0.12em\", color:\"rgba(196,181,253,0.7)\", marginBottom:12, textTransform:\"uppercase\" }}>PRICING</p>\n        <h2 style={{ fontFamily:\"'Fraunces',Georgia,serif\", fontSize:\"clamp(28px,5vw,48px)\", fontWeight:500, letterSpacing:\"-0.03em\", color:\"#fff\", margin:\"0 0 10px\", lineHeight:1.1 }}>\n          Start free.<br/>\n          <em style={{ fontStyle:\"italic\", color:\"#C4B5FD\" }}>Scale when you're ready.</em>\n        </h2>\n\n        {/* Location badge */}\n        {p.badge && (\n          <div style={{ display:\"inline-flex\", alignItems:\"center\", gap:6, margin:\"14px 0 32px\", padding:\"6px 14px\", borderRadius:99, background:\"rgba(255,255,255,0.08)\", border:\"1px solid rgba(255,255,255,0.12)\" }}>\n            <span style={{ fontSize:12, color:\"rgba(255,255,255,0.7)\", fontWeight:500 }}>{p.badge}</span>\n            <span style={{ fontSize:11, color:\"rgba(196,181,253,0.6)\" }}>· {p.tagline}</span>\n          </div>\n        )}\n        {!p.badge && <p style={{ fontSize:14, color:\"rgba(255,255,255,0.5)\", marginBottom:36 }}>{p.tagline}</p>}\n\n        <div style={{ display:\"grid\", gridTemplateColumns:\"repeat(3,1fr)\", gap:14, marginBottom:36 }} className=\"price-grid\">\n          {plans.map(plan => (\n            <div key={plan.name} style={{\n              background: plan.highlight ? \"rgba(255,255,255,0.1)\" : \"rgba(255,255,255,0.04)\",\n              borderRadius:20, padding:\"28px 24px\",\n              border: plan.highlight ? \"1px solid rgba(196,181,253,0.35)\" : \"1px solid rgba(255,255,255,0.08)\",\n              position:\"relative\",\n            }}>\n              {plan.highlight && (\n                <div style={{ position:\"absolute\", top:-12, left:\"50%\", transform:\"translateX(-50%)\", background:\"#C4B5FD\", color:\"#130D2E\", fontSize:10, fontWeight:800, padding:\"4px 14px\", borderRadius:99, letterSpacing:\"0.06em\", whiteSpace:\"nowrap\" }}>\n                  MOST POPULAR\n                </div>\n              )}\n              <p style={{ fontSize:13, fontWeight:700, color:\"rgba(196,181,253,0.8)\", margin:\"0 0 8px\" }}>{plan.name}</p>\n              <div style={{ display:\"flex\", alignItems:\"baseline\", gap:4, marginBottom:20 }}>\n                <span style={{ fontSize:30, fontWeight:900, color:\"#fff\", letterSpacing:\"-0.03em\" }}>{plan.price}</span>\n                <span style={{ fontSize:12, color:\"rgba(255,255,255,0.4)\" }}>{p.period}</span>\n              </div>\n              {plan.features.map(f => (\n                <div key={f} style={{ display:\"flex\", alignItems:\"center\", gap:8, marginBottom:10 }}>\n                  <Check size={11} color=\"#A78BFA\" strokeWidth={2.5}/>\n                  <span style={{ fontSize:12, color:\"rgba(255,255,255,0.65)\" }}>{f}</span>\n                </div>\n              ))}\n            </div>\n          ))}\n        </div>\n\n        <p style={{ fontSize:11, color:\"rgba(255,255,255,0.3)\", marginBottom:24 }}>\n          2% transaction fee on all plans · Cancel anytime\n        </p>\n        <Link href=\"/auth/register\" style={{ display:\"inline-flex\", alignItems:\"center\", gap:8, padding:\"14px 32px\", borderRadius:14, background:\"#fff\", color:C.navy, textDecoration:\"none\", fontSize:14, fontWeight:700, boxShadow:\"0 8px 24px rgba(0,0,0,0.2)\" }}>\n          Start for free <ArrowRight size={14}/>\n        </Link>\n      </div>\n      <style>{`@media(max-width:768px){ .price-grid{grid-template-columns:1fr!important;} }`}</style>\n    </section>\n  );\n}\n\n// ─── Social Proof ──────────────────────────────────────────────────────────────\nfunction SocialProof() {\n  const stats = [\n    { value: \"29\",   label: \"Store templates\" },\n    { value: \"60s\",  label: \"To launch a store\" },\n    { value: \"54+\",  label: \"Backend features\" },\n    { value: \"100%\", label: \"Uptime SLA\" },\n  ];\n\n  return (\n    <section style={{ padding: \"80px 24px\", maxWidth: 960, margin: \"0 auto\" }}>\n      <div style={{ display: \"grid\", gridTemplateColumns: \"repeat(4,1fr)\", gap: 24, textAlign: \"center\" }} className=\"stats-grid\">\n        {stats.map((s, i) => (\n          <motion.div key={s.label}\n            initial={{ opacity: 0, y: 12 }} whileInView={{ opacity: 1, y: 0 }}\n            transition={{ delay: i * 0.1 }} viewport={{ once: true }}>\n            <p style={{\n              fontFamily: \"'Fraunces', Georgia, serif\",\n              fontSize: \"clamp(36px, 6vw, 56px)\", fontWeight: 500,\n              color: C.navy, margin: \"0 0 6px\", letterSpacing: \"-0.04em\",\n              lineHeight: 1,\n            }}>{s.value}</p>\n            <p style={{ fontSize: 13, color: C.muted, margin: 0 }}>{s.label}</p>\n          </motion.div>\n        ))}\n      </div>\n      <style>{`@media(max-width:768px){ .stats-grid{grid-template-columns:1fr 1fr!important; gap:32px!important;} }`}</style>\n    </section>\n  );\n}\n\n// ─── CTA ──────────────────────────────────────────────────────────────────────\nfunction FinalCTA() {\n  return (\n    <section style={{ padding: \"100px 24px\", textAlign: \"center\" }}>\n      <motion.div initial={{ opacity: 0, y: 20 }} whileInView={{ opacity: 1, y: 0 }} viewport={{ once: true }}>\n        <h2 style={{\n          fontFamily: \"'Fraunces', Georgia, serif\",\n          fontSize: \"clamp(32px, 6vw, 60px)\", fontWeight: 500, letterSpacing: \"-0.04em\",\n          color: C.navy, margin: \"0 0 18px\", lineHeight: 1.08,\n        }}>\n          Your store is<br/>\n          <em style={{ fontStyle: \"italic\", color: C.purple }}>60 seconds away.</em>\n        </h2>\n        <p style={{ fontSize: 16, color: C.muted, maxWidth: 400, margin: \"0 auto 40px\", lineHeight: 1.6 }}>\n          No inventory. No coding. Just KIRO and a product idea.\n          The rest takes care of itself.\n        </p>\n        <Link href=\"/auth/register\" style={{\n          display: \"inline-flex\", alignItems: \"center\", gap: 10,\n          padding: \"16px 36px\", borderRadius: 16,\n          background: C.navy, color: \"#fff\",\n          textDecoration: \"none\", fontSize: 16, fontWeight: 700,\n          boxShadow: \"0 8px 32px rgba(19,13,46,0.2)\",\n          letterSpacing: \"-0.01em\",\n        }}\n        onMouseEnter={e => { e.currentTarget.style.transform = \"translateY(-2px)\"; }}\n        onMouseLeave={e => { e.currentTarget.style.transform = \"translateY(0)\"; }}>\n          Launch your store free <ArrowRight size={16}/>\n        </Link>\n        <p style={{ fontSize: 12, color: C.muted, marginTop: 16 }}>\n          No credit card · Free plan forever · Cancel anytime\n        </p>\n      </motion.div>\n    </section>\n  );\n}\n\n// ─── Footer ───────────────────────────────────────────────────────────────────\nfunction Footer() {\n  return (\n    <footer style={{\n      borderTop: `1px solid ${C.border}`, padding: \"40px 24px\",\n      background: \"#fff\",\n    }}>\n      <div style={{ maxWidth: 960, margin: \"0 auto\", display: \"flex\", flexWrap: \"wrap\", alignItems: \"center\", justifyContent: \"space-between\", gap: 16 }}>\n        <div style={{ display: \"flex\", alignItems: \"center\", gap: 10 }}>\n          <div style={{ width: 28, height: 28, borderRadius: 8, background: \"linear-gradient(145deg,#2D1B69,#0D0625)\", display: \"flex\", alignItems: \"center\", justifyContent: \"center\" }}>\n            <svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\"><path d=\"M13 2L3 14h9l-1 8 10-12h-9z\" fill=\"white\"/></svg>\n          </div>\n          <span style={{ fontSize: 14, fontWeight: 800, color: C.navy, letterSpacing: \"-0.02em\" }}>DropOS</span>\n          <span style={{ fontSize: 12, color: C.muted }}>© 2026</span>\n        </div>\n        <div style={{ display: \"flex\", gap: 20 }}>\n          {[\"Pricing\", \"Features\", \"Privacy\", \"Terms\"].map(l => (\n            <Link key={l} href={`/${l.toLowerCase()}`}\n              style={{ fontSize: 12, color: C.muted, textDecoration: \"none\", fontWeight: 500 }}>\n              {l}\n            </Link>\n          ))}\n        </div>\n      </div>\n    </footer>\n  );\n}\n\n// ─── Main ─────────────────────────────────────────────────────────────────────\nexport default function HomePage() {\n  return (\n    <div style={{ background: C.bg, fontFamily: \"'Plus Jakarta Sans', -apple-system, system-ui, sans-serif\", overflowX: \"hidden\" }}>\n      <style>{`\n        @import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800;900&display=swap');\n        @import url('https://fonts.googleapis.com/css2?family=Fraunces:ital,wght@0,400;0,500;0,600;0,700;0,800;0,900;1,400;1,500;1,600;1,700;1,800;1,900&display=swap');\n        *{box-sizing:border-box;margin:0;padding:0;}\n        html{scroll-behavior:smooth;}\n      `}</style>\n      <Nav />\n      <Hero />\n      <SocialProof />\n      <Features />\n      <PricingPreview />\n      <FinalCTA />\n      <Footer />\n    </div>\n  );\n}\n","frontend/src/app/dashboard/page.tsx":"\"use client\";\nimport { useState, useEffect } from \"react\";\nimport { useQuery } from \"@tanstack/react-query\";\nimport { motion } from \"framer-motion\";\nimport Link from \"next/link\";\n// currency formatting handled inline\nimport {\n  TrendingUp, ShoppingCart, Users, Package, Zap,\n  ChevronRight, Store, Flame, Activity, ArrowUpRight,\n  AlertCircle, Clock, CheckCircle2, RefreshCw\n} from \"lucide-react\";\nimport { useTheme } from \"../../components/layout/DashboardLayout\";\nimport { useAuthStore } from \"../../store/auth.store\";\nimport { api } from \"../../lib/api\";\nimport { OpportunityFeed } from \"../../components/kai/OpportunityFeed\";\n\nconst V = { v500: \"#6B35E8\", v400: \"#8B5CF6\", v300: \"#A78BFA\", cyan: \"#06B6D4\", green: \"#10B981\", amber: \"#F59E0B\", red: \"#EF4444\" };\n\nconst fmt = (n: number) => new Intl.NumberFormat(\"en-NG\", { style:\"currency\", currency:\"NGN\", maximumFractionDigits:0 }).format(n||0);\n\nfunction StatCard({ label, value, delta, color, icon: Icon, delay = 0 }: any) {\n  const { theme } = useTheme();\n  const isDark = theme === \"dark\";\n  const t = { card: isDark ? \"#181230\" : \"#fff\", border: isDark ? \"rgba(255,255,255,0.06)\" : \"rgba(15,5,32,0.07)\", text: isDark ? \"#fff\" : \"#0D0918\", muted: isDark ? \"rgba(255,255,255,0.38)\" : \"rgba(13,9,24,0.45)\" };\n  return (\n    <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay }}\n      style={{ padding: 18, borderRadius: 16, background: t.card, border: `1px solid ${t.border}` }}>\n      <div style={{ display: \"flex\", alignItems: \"center\", justifyContent: \"space-between\", marginBottom: 12 }}>\n        <div style={{ width: 36, height: 36, borderRadius: 10, display: \"flex\", alignItems: \"center\", justifyContent: \"center\", background: `${color}18` }}>\n          <Icon size={16} color={color} />\n        </div>\n        {delta !== undefined && (\n          <span style={{ fontSize: 11, fontWeight: 700, color: delta >= 0 ? V.green : V.red, background: delta >= 0 ? \"rgba(16,185,129,0.1)\" : \"rgba(239,68,68,0.1)\", padding: \"3px 8px\", borderRadius: 99 }}>\n            {delta >= 0 ? \"+\" : \"\"}{delta}%\n          </span>\n        )}\n      </div>\n      <p style={{ fontSize: 22, fontWeight: 900, color: t.text, letterSpacing: \"-0.04em\", lineHeight: 1 }}>{value}</p>\n      <p style={{ fontSize: 12, color: t.muted, marginTop: 4 }}>{label}</p>\n    </motion.div>\n  );\n}\n\nfunction OrderRow({ order, t }: any) {\n  const statusColors: Record<string, string> = {\n    PENDING: V.amber, COMPLETED: V.green, SHIPPED: V.cyan,\n    DELIVERED: V.v400, CANCELLED: V.red, PROCESSING: V.cyan,\n  };\n  const color = statusColors[order.status] || V.amber;\n  return (\n    <div style={{ display: \"flex\", alignItems: \"center\", gap: 12, padding: \"10px 0\", borderBottom: `1px solid ${t.border}` }}>\n      <div style={{ width: 32, height: 32, borderRadius: 8, background: `${color}15`, display: \"flex\", alignItems: \"center\", justifyContent: \"center\", flexShrink: 0 }}>\n        <ShoppingCart size={13} color={color} />\n      </div>\n      <div style={{ flex: 1, minWidth: 0 }}>\n        <p style={{ fontSize: 13, fontWeight: 600, color: t.text, whiteSpace: \"nowrap\", overflow: \"hidden\", textOverflow: \"ellipsis\" }}>\n          {order.customerName || \"Customer\"}\n        </p>\n        <p style={{ fontSize: 11, color: t.muted, marginTop: 1 }}>#{order.orderNumber || order.id?.slice(-6)}</p>\n      </div>\n      <div style={{ textAlign: \"right\", flexShrink: 0 }}>\n        <p style={{ fontSize: 13, fontWeight: 700, color: t.text }}>{fmt(order.total)}</p>\n        <span style={{ fontSize: 10, fontWeight: 700, color, background: `${color}15`, padding: \"2px 6px\", borderRadius: 99 }}>\n          {order.status}\n        </span>\n      </div>\n    </div>\n  );\n}\n\nexport default function DashboardPage() {\n  const { theme } = useTheme();\n  const { user } = useAuthStore();\n  const isDark = theme === \"dark\";\n  const [greeting, setGreeting] = useState(\"morning\");\n  const storeCurrency = (user?.stores?.[0] as any)?.currency || \"NGN\";\n  const fmtCurrency = (n: number) => {\n    const symbol = storeCurrency === \"NGN\" ? \"₦\" : storeCurrency === \"GBP\" ? \"£\" : storeCurrency === \"USD\" ? \"$\" : \"₦\";\n    return `${symbol}${(n || 0).toLocaleString(\"en-NG\", { maximumFractionDigits: 0 })}`;\n  };\n  const firstName = user?.name?.split(\" \")[0] || user?.email?.split(\"@\")[0] || \"there\";\n  const storeId = user?.stores?.[0]?.id;\n  const storeSlug = user?.stores?.[0]?.slug;\n\n  useEffect(() => {\n    const h = new Date().getHours();\n    setGreeting(h < 12 ? \"morning\" : h < 17 ? \"afternoon\" : \"evening\");\n  }, []);\n\n  const t = {\n    card:   isDark ? \"#181230\" : \"#fff\",\n    border: isDark ? \"rgba(255,255,255,0.06)\" : \"rgba(15,5,32,0.07)\",\n    text:   isDark ? \"#fff\"    : \"#0D0918\",\n    muted:  isDark ? \"rgba(255,255,255,0.38)\" : \"rgba(13,9,24,0.45)\",\n    faint:  isDark ? \"rgba(255,255,255,0.03)\" : \"rgba(15,5,32,0.02)\",\n  };\n\n  const { data: analytics } = useQuery({\n    queryKey: [\"dashboard-analytics\", storeId],\n    queryFn:  () => api.get(`/analytics/${storeId}?period=7`).then(r => r.data.data),\n    enabled:  !!storeId,\n    staleTime: 60000,\n  });\n\n  const { data: recentOrders } = useQuery({\n    queryKey: [\"dashboard-orders\", storeId],\n    queryFn:  () => api.get(`/orders/${storeId}?limit=5`).then(r => r.data.data?.orders || r.data.data || []),\n    enabled:  !!storeId,\n    staleTime: 30000,\n  });\n\n  // Direct product count — more reliable than analytics which may be cached\n  const { data: productCount } = useQuery({\n    queryKey: [\"dashboard-product-count\", storeId],\n    queryFn:  () => api.get(`/products/${storeId}?limit=1`).then(r => r.data.data?.total || r.data.total || (Array.isArray(r.data.data) ? r.data.data.length : 0)),\n    enabled:  !!storeId,\n    staleTime: 60000,\n  });\n\n  const { data: pulse } = useQuery({\n    queryKey: [\"kiro-pulse\", storeId],\n    queryFn:  () => api.get(`/kai/pulse?storeId=${storeId}&limit=3`).then(r => r.data.data || []),\n    enabled:  !!storeId,\n    staleTime: 120000,\n  });\n\n  const stats = analytics?.summary || analytics?.stats || {};\n  const orders = Array.isArray(recentOrders) ? recentOrders : [];\n  // Deduplicate by type — keep most recent of each type, max 4\n  const seen = new Set<string>();\n  const alerts = (Array.isArray(pulse) ? pulse : [])\n    .filter((a: any) => { if (seen.has(a.type)) return false; seen.add(a.type); return true; })\n    .slice(0, 4);\n\n  const statCards = [\n    { label: \"Revenue (7d)\",  value: fmtCurrency(stats.revenue || 0),        delta: stats.revenueDelta,  color: V.v400,  icon: TrendingUp  },\n    { label: \"Orders (7d)\",   value: (stats.orders    || 0).toLocaleString(), delta: stats.ordersDelta,   color: V.cyan,  icon: ShoppingCart },\n    { label: \"Customers\",     value: (stats.customers || 0).toLocaleString(), delta: undefined,            color: V.green, icon: Users        },\n    { label: \"Products\",      value: (productCount || stats.products || analytics?.totalProducts || 0).toLocaleString(), delta: undefined, color: V.amber, icon: Package },\n  ];\n\n  const quickActions = [\n    { label: \"Add Product\",  href: \"/dashboard/products\",   icon: Package,   color: V.v400  },\n    { label: \"View Store\",   href: storeSlug ? `/store/${storeSlug}` : \"/dashboard/stores\", icon: Store, color: V.cyan, target: \"_blank\" },\n    { label: \"Flash Sale\",   href: \"/dashboard/flash-sales\",icon: Flame,     color: V.amber },\n    { label: \"Analytics\",    href: \"/dashboard/analytics\",  icon: Activity,  color: V.green },\n  ];\n\n  return (\n    <div style={{ maxWidth: 1200, margin: \"0 auto\" }}>\n      {/* Header */}\n      <motion.div initial={{ opacity: 0, y: -8 }} animate={{ opacity: 1, y: 0 }} style={{ marginBottom: 24 }}>\n        <h1 style={{ fontSize: 22, fontWeight: 900, letterSpacing: \"-0.04em\", color: t.text, marginBottom: 4 }}>\n          Good {greeting}, {firstName} 👋\n        </h1>\n        <p style={{ fontSize: 13, color: t.muted }}>\n          {user?.stores?.[0]?.name || \"Your store\"} · {new Date().toLocaleDateString(\"en-NG\", { weekday: \"long\", day: \"numeric\", month: \"long\" })}\n        </p>\n      </motion.div>\n\n      {/* Stats */}\n      <div style={{ display: \"grid\", gridTemplateColumns: \"repeat(4,1fr)\", gap: 12, marginBottom: 20 }} className=\"grid-cols-2 sm:grid-cols-4\">\n        {statCards.map((s, i) => <StatCard key={s.label} {...s} delay={i * 0.07} />)}\n      </div>\n\n      <div style={{ display: \"grid\", gridTemplateColumns: \"1fr 340px\", gap: 16 }} className=\"grid-1col lg:grid-2col\">\n        {/* Left: Recent Orders */}\n        <div>\n          <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.3 }}\n            style={{ padding: 18, borderRadius: 16, background: t.card, border: `1px solid ${t.border}`, marginBottom: 16 }}>\n            <div style={{ display: \"flex\", alignItems: \"center\", justifyContent: \"space-between\", marginBottom: 14 }}>\n              <span style={{ fontSize: 13, fontWeight: 700, color: t.text }}>Recent Orders</span>\n              <Link href=\"/dashboard/orders\" style={{ display: \"flex\", alignItems: \"center\", gap: 4, fontSize: 12, color: V.v400, textDecoration: \"none\", fontWeight: 600 }}>\n                View all <ChevronRight size={13} />\n              </Link>\n            </div>\n            {orders.length === 0 ? (\n              <div style={{ textAlign: \"center\", padding: \"28px 0\" }}>\n                <ShoppingCart size={28} style={{ color: t.muted, margin: \"0 auto 8px\" }} />\n                <p style={{ fontSize: 12, color: t.muted }}>No orders yet. Share your store link to get your first sale.</p>\n                {storeSlug && (\n                  <a href={`/store/${storeSlug}`} target=\"_blank\" rel=\"noreferrer\"\n                    style={{ display: \"inline-flex\", alignItems: \"center\", gap: 6, marginTop: 12, fontSize: 12, fontWeight: 700, color: V.v400, textDecoration: \"none\", background: \"rgba(107,53,232,0.08)\", padding: \"6px 14px\", borderRadius: 99, border: \"1px solid rgba(107,53,232,0.2)\" }}>\n                    <Store size={11} /> View your store <ArrowUpRight size={11} />\n                  </a>\n                )}\n              </div>\n            ) : (\n              <div>\n                {orders.slice(0, 5).map((o: any) => <OrderRow key={o.id} order={o} t={t} />)}\n              </div>\n            )}\n          </motion.div>\n\n          {/* KIRO Opportunity Feed - proactive intelligence */}\n          {storeId && <OpportunityFeed storeId={storeId} isDark={isDark} onAction={(action) => {\n            // Trigger KIRO chat with the action\n            if (typeof window !== \"undefined\") {\n              window.dispatchEvent(new CustomEvent(\"kiro:execute\", { detail: { prompt: action } }));\n            }\n          }}/>}\n\n          {/* KIRO Pulse Alerts */}\n          {alerts.length > 0 && (\n            <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.4 }}\n              style={{ padding: 18, borderRadius: 16, background: t.card, border: `1px solid ${t.border}` }}>\n              <div style={{ display: \"flex\", alignItems: \"center\", gap: 8, marginBottom: 14 }}>\n                <Zap size={14} color={V.v400} />\n                <span style={{ fontSize: 13, fontWeight: 700, color: t.text }}>KIRO Alerts</span>\n              </div>\n              <div style={{ display: \"flex\", flexDirection: \"column\", gap: 8 }}>\n                {alerts.map((a: any) => (\n                  <div key={a.id} style={{ display: \"flex\", gap: 10, padding: 10, borderRadius: 10, background: t.faint, border: `1px solid ${t.border}` }}>\n                    <AlertCircle size={13} color={a.severity === \"high\" ? V.red : V.amber} style={{ flexShrink: 0, marginTop: 1 }} />\n                    <div>\n                      <p style={{ fontSize: 12, fontWeight: 600, color: t.text }}>{a.title}</p>\n                      <p style={{ fontSize: 11, color: t.muted, marginTop: 2 }}>{a.message}</p>\n                    </div>\n                  </div>\n                ))}\n              </div>\n            </motion.div>\n          )}\n        </div>\n\n        {/* Right column */}\n        <div style={{ display: \"flex\", flexDirection: \"column\", gap: 14 }}>\n          {/* KIRO CTA */}\n          <motion.div initial={{ opacity: 0, x: 16 }} animate={{ opacity: 1, x: 0 }} transition={{ delay: 0.25 }}\n            style={{ padding: 18, borderRadius: 16, background: \"linear-gradient(135deg,#2D1B69,#1a0f3c)\", border: \"1px solid rgba(107,53,232,0.3)\", position: \"relative\", overflow: \"hidden\" }}>\n            <div style={{ position: \"absolute\", top: -20, right: -20, width: 80, height: 80, borderRadius: \"50%\", background: \"rgba(107,53,232,0.15)\" }} />\n            <div style={{ display: \"flex\", alignItems: \"center\", gap: 8, marginBottom: 8 }}>\n              <div style={{ width: 28, height: 28, borderRadius: 8, background: \"rgba(107,53,232,0.3)\", display: \"flex\", alignItems: \"center\", justifyContent: \"center\" }}>\n                <Zap size={13} color={V.v300} />\n              </div>\n              <span style={{ fontSize: 12, fontWeight: 700, color: V.v300 }}>KIRO</span>\n            </div>\n            <p style={{ fontSize: 13, fontWeight: 700, color: \"#fff\", marginBottom: 6 }}>What do you want to build today?</p>\n            <p style={{ fontSize: 11, color: \"rgba(255,255,255,0.5)\", marginBottom: 14, lineHeight: 1.5 }}>\n              Import products, write copy, run a sale, or just ask anything about your store.\n            </p>\n            <Link href=\"/kiro\">\n              <button style={{ width: \"100%\", padding: \"9px 0\", borderRadius: 10, border: \"none\", cursor: \"pointer\", background: \"rgba(107,53,232,0.4)\", color: \"#fff\", fontSize: 12, fontWeight: 700, display: \"flex\", alignItems: \"center\", justifyContent: \"center\", gap: 6 }}>\n                <Zap size={12} /> Chat with KIRO\n              </button>\n            </Link>\n          </motion.div>\n\n          {/* Quick Actions */}\n          <motion.div initial={{ opacity: 0, x: 16 }} animate={{ opacity: 1, x: 0 }} transition={{ delay: 0.32 }}\n            style={{ padding: 18, borderRadius: 16, background: t.card, border: `1px solid ${t.border}` }}>\n            <span style={{ fontSize: 13, fontWeight: 700, color: t.text, display: \"block\", marginBottom: 12 }}>Quick Actions</span>\n            <div style={{ display: \"grid\", gridTemplateColumns: \"1fr 1fr\", gap: 8 }}>\n              {quickActions.map(a => {\n                const Icon = a.icon;\n                return (\n                  <Link key={a.label} href={a.href} target={(a as any).target} style={{ textDecoration: \"none\" }}>\n                    <motion.div whileHover={{ scale: 1.02 }} whileTap={{ scale: 0.97 }}\n                      style={{ display: \"flex\", flexDirection: \"column\", alignItems: \"center\", gap: 7, padding: 12, borderRadius: 12, cursor: \"pointer\", background: t.faint, border: `1px solid ${t.border}` }}>\n                      <div style={{ width: 30, height: 30, borderRadius: 9, display: \"flex\", alignItems: \"center\", justifyContent: \"center\", background: `${a.color}15` }}>\n                        <Icon size={14} color={a.color} />\n                      </div>\n                      <span style={{ fontSize: 11, fontWeight: 600, color: t.muted, textAlign: \"center\" }}>{a.label}</span>\n                    </motion.div>\n                  </Link>\n                );\n              })}\n            </div>\n          </motion.div>\n\n          {/* Store status */}\n          <motion.div initial={{ opacity: 0, x: 16 }} animate={{ opacity: 1, x: 0 }} transition={{ delay: 0.38 }}\n            style={{ padding: 18, borderRadius: 16, background: t.card, border: `1px solid ${t.border}` }}>\n            <span style={{ fontSize: 13, fontWeight: 700, color: t.text, display: \"block\", marginBottom: 12 }}>Store Status</span>\n            <div style={{ display: \"flex\", flexDirection: \"column\", gap: 8 }}>\n              {[\n                { label: \"Store live\",     done: !!user?.stores?.[0]?.id,                                                                               icon: Store        },\n                { label: \"Products added\", done: (productCount || stats?.products || analytics?.totalProducts || 0) > 0,              icon: Package      },\n                { label: \"First order\",    done: orders.length > 0 || (stats?.orders || analytics?.totalOrders || 0) > 0,                             icon: ShoppingCart },\n                { label: \"Payment setup\",  done: !!(user?.stores?.[0] as any)?.paystackPublicKey || !!(user?.stores?.[0] as any)?.stripeAccountId || !!(user?.stores?.[0] as any)?.currency, icon: CheckCircle2 },\n              ].map(item => {\n                const Icon = item.icon;\n                return (\n                  <div key={item.label} style={{ display: \"flex\", alignItems: \"center\", gap: 8 }}>\n                    <div style={{ width: 22, height: 22, borderRadius: 6, display: \"flex\", alignItems: \"center\", justifyContent: \"center\", background: item.done ? \"rgba(16,185,129,0.1)\" : t.faint, flexShrink: 0 }}>\n                      <Icon size={11} color={item.done ? V.green : t.muted} />\n                    </div>\n                    <span style={{ fontSize: 12, color: item.done ? t.text : t.muted, flex: 1 }}>{item.label}</span>\n                    {item.done\n                      ? <CheckCircle2 size={13} color={V.green} />\n                      : <Clock size={13} style={{ color: t.muted }} />}\n                  </div>\n                );\n              })}\n            </div>\n          </motion.div>\n        </div>\n      </div>\n\n      <style>{`\n        @media(max-width:900px){\n          .grid-cols-2{grid-template-columns:1fr 1fr!important}\n          .grid-1col.lg\\\\:grid-2col{grid-template-columns:1fr!important}\n        }\n        @media(max-width:480px){\n          .grid-cols-2{grid-template-columns:1fr 1fr!important}\n        }\n      `}</style>\n    </div>\n  );\n}\n"};
for(const[rel,c]of Object.entries(files)){const p=rel.split('/').join(path.sep);fs.mkdirSync(path.dirname(p),{recursive:true});fs.writeFileSync(p,c,'utf8');console.log('✓',rel.split('/').slice(-2).join('/'));}
try{execSync('git add .',{stdio:'inherit'});const st=execSync('git status --short',{encoding:'utf8'}).trim();if(st){execSync('git commit -m "fix: unified nav, global copy, location pricing, accurate stats"',{stdio:'inherit'});}execSync('git push origin main',{stdio:'inherit'});console.log('\n✅ Pushed!');process.chdir('frontend');execSync('vercel --prod --force',{stdio:'inherit'});console.log('\n🚀 LIVE');}catch(e){console.log(e.message);console.log('Run: cd frontend && vercel --prod --force');}